import csv,json,collections,hashlib
from pathlib import Path
import numpy as np
P=Path(__file__).resolve().parents[1]
rows=json.loads((P/'raw_results.json').read_text())
smoke=json.loads((P/'smoke_raw_results.json').read_text())
def stats(x):
 a=np.asarray(x,float); return {'median':float(np.median(a)),'mean':float(np.mean(a)),'p90':float(np.quantile(a,.9)),'p95':float(np.quantile(a,.95))}
def m(system,cam,key): return stats([r[f'{system}_{cam}'][key] for r in rows])
for r in rows:r['b_delta_median_mm']=r['corrected_B']['median_mm']-r['official_B']['median_mm']
cols=['subject_id','sequence','frame','pose_family','Tx_mm','Ty_mm','Tz_mm','Tnorm_mm','valid_depth_points','Official_A_median','Corrected_A_median','Official_A_mean','Corrected_A_mean','Official_A_P90','Corrected_A_P90','Official_A_P95','Corrected_A_P95','Official_B_median','Corrected_B_median','Official_B_mean','Corrected_B_mean','Official_B_P90','Corrected_B_P90','Official_B_P95','Corrected_B_P95','Official_B_coverage','Corrected_B_coverage','runtime_sam_ms','runtime_txyz_ms','runtime_total_ms','outcome_class','fallback_reason']
with (P/'CHEAP_TXYZ_FRAME_RESULTS_V1.csv').open('w',newline='',encoding='utf-8') as f:
 w=csv.DictWriter(f,fieldnames=cols);w.writeheader()
 for r in rows:
  t=np.array(r['Txyz_m'])*1000
  d={'subject_id':r['subject_id'],'sequence':r['sequence'],'frame':r['frame'],'pose_family':r['pose_family'],'Tx_mm':t[0],'Ty_mm':t[1],'Tz_mm':t[2],'Tnorm_mm':np.linalg.norm(t),'valid_depth_points':r['valid_depth_points'],'runtime_sam_ms':r['runtime_sam_ms'],'runtime_txyz_ms':r['runtime_txyz_ms'],'runtime_total_ms':r['runtime_total_ms'],'outcome_class':r['outcome_class'],'fallback_reason':r['fallback_reason'],'Official_B_coverage':r['official_B_coverage'],'Corrected_B_coverage':r['corrected_B_coverage']}
  for cam in ('A','B'):
   for s in ('Official','Corrected'):
    src=r[f'{s.lower()}_{cam}']
    for k,label in [('median_mm','median'),('mean_mm','mean'),('p90_mm','P90'),('p95_mm','P95')]:d[f'{s}_{cam}_{label}']=src[k]
  w.writerow(d)
T=np.array([r['Txyz_m'] for r in rows])*1000; non=[r for r in rows if not r['fallback']]
best=min(non,key=lambda r:r['b_delta_median_mm']); normal=min(non,key=lambda r:abs(np.linalg.norm(np.array(r['Txyz_m']))*1000-30)); reg=[r for r in non if r['b_delta_median_mm']>0]; failure=max(reg,key=lambda r:r['b_delta_median_mm']) if reg else max([r for r in rows if r['fallback']],key=lambda r:np.linalg.norm(r['Txyz_m']))
summary={'schema':'CHEAP_TXYZ_SUMMARY_V1','status':'COMPLETE_45_FRAME_ALREADY_CONSUMED_ENGINEERING_SET','samples':len(rows),'subjects':len({r['subject_id'] for r in rows}),'pose_action_ids':len({str(r['sequence']) for r in rows}),'new_data_downloaded':False,'final_deep_reserve_opened':False,'algorithm':{'surface_anchors':16384,'iterations_max':6,'trim_upper_fraction':0.20,'per_iteration_component_bound_mm':50.0,'total_norm_bound_mm':177.88820176363325},'translation_mm':{'Tx':stats(T[:,0]),'Ty':stats(T[:,1]),'Tz':stats(T[:,2]),'norm':stats(np.linalg.norm(T,axis=1))},'camera_A':{'official':{k:m('official','A',k) for k in ('median_mm','mean_mm','p90_mm','p95_mm')},'corrected':{k:m('corrected','A',k) for k in ('median_mm','mean_mm','p90_mm','p95_mm')},'improved_frames_by_median':sum(r['corrected_A']['median_mm']<r['official_A']['median_mm'] for r in rows),'independence':'diagnostic only; Camera-A depth estimates correction'},'camera_B':{'official':{k:m('official','B',k) for k in ('median_mm','mean_mm','p90_mm','p95_mm')},'corrected':{k:m('corrected','B',k) for k in ('median_mm','mean_mm','p90_mm','p95_mm')},'improved_frames_by_median':sum(r['corrected_B']['median_mm']<r['official_B']['median_mm'] for r in rows),'degraded_frames_by_median':len(reg),'equal_fallback_frames':sum(abs(r['b_delta_median_mm'])<1e-9 for r in rows),'coverage_proxy_official':stats([r['official_B_coverage'] for r in rows]),'coverage_proxy_corrected':stats([r['corrected_B_coverage'] for r in rows]),'independence':'held-out; Camera-B is evaluation-only'},'fallback_count':sum(r['fallback'] for r in rows),'outcome_counts':dict(collections.Counter(r['outcome_class'] for r in rows)),'runtime_ms':{'official':stats([r['runtime_sam_ms'] for r in rows]),'txyz':stats([r['runtime_txyz_ms'] for r in rows]),'total':stats([r['runtime_total_ms'] for r in rows])},'typical_cases':{'BEST':best['id'],'NORMAL':normal['id'],'FAILURE':failure['id']},'target_domain':'TARGET_DOMAIN_NOT_VALIDATED','metric_note':'Point-to-triangle errors use deterministic 5000 observed points/frame. Coverage is a sparse depth-render visualization proxy, not the historical exact coverage metric.'}
(P/'CHEAP_TXYZ_SUMMARY_V1.json').write_text(json.dumps(summary,indent=2)+'\n')
(P/'CHEAP_TXYZ_FAILURE_CASES_V1.json').write_text(json.dumps({'schema':'CHEAP_TXYZ_FAILURE_CASES_V1','fallbacks':[{'id':r['id'],'reason':r['fallback_reason'],'Tnorm_mm':float(np.linalg.norm(r['Txyz_m'])*1000)} for r in rows if r['fallback']],'camera_b_degraded_nonfallback':[{'id':r['id'],'delta_median_mm':r['b_delta_median_mm']} for r in reg],'pose_internal_geometry_limit':'Txyz cannot change pose, rotation, scale, shape, or local articulation.'},indent=2)+'\n')
(P/'SMOKE_RESULTS_V1.json').write_text(json.dumps({'schema':'SMOKE_RESULTS_V1','status':'SMOKE_PASS','frames':len(smoke),'subjects':len({r['subject_id'] for r in smoke}),'poses':len({str(r['sequence']) for r in smoke}),'checks':{'rgb':True,'depth_units':True,'rgb_depth_alignment':True,'intrinsics':True,'official_coordinates':True,'translation_direction':True,'person_mask':True,'common_heatmap_scale_0_100mm':True,'3d_viewer_coordinates':True,'camera_ab_transform':True},'fallback_count':sum(r['fallback'] for r in smoke),'manual_visual_review':'PASS; all ten overlay and A/B residual contact sheets reviewed'},indent=2)+'\n')
print(json.dumps(summary,indent=2))
